```python
def solve(values):
    if not values:
        return 0
    max_sum = sum(values[:2])
    start = 0
    for i in range(1, len(values) - 1):
        current_sum = values[i] + values[i + 1]
        if current_sum > max_sum:
            max_sum = current_sum
            start = i
    return start
```

